mapper.select:
SELECT min(t.noTaxPrices) AS noTaxPrice, concat(t.materialCode, '-', t.areaCode) AS materialArea, t.* FROM ( SELECT DATE_FORMAT(a.CREATION_DATE, '%Y-%m') AS ym, a.CEEA_UNIT_NO_TAX_PRICE AS noTaxPrices, a.MATERIAL_CODE AS materialCode, a.MATERIAL_NAME AS materialName, ( SELECT sbdi.DICT_ITEM_NAME FROM meicloud_usrm_cloud_biz_base.scc_base_dict_item sbdi LEFT JOIN meicloud_usrm_cloud_biz_base.scc_base_dict sbd ON sbdi.DICT_ID = sbd.DICT_ID WHERE sbd.DICT_CODE = 'REGION' AND sbd.`LANGUAGE` = 'zh_CN' AND sbdi.DICT_ITEM_CODE = a.EXT_AREA_CODE) AS areaCode, a.EXT_BRAND AS brand, a.COMMENTS AS materialDescribe, b.CEEA_ORG_CODE AS orgCode, b.CEEA_ORG_NAME AS orgNmae, a.CEEA_TAX_RATE AS taxPrice, a.DELIVERY_DATE AS leadTime, b.VENDOR_CODE AS supCode, b.VENDOR_NAME AS supName, b.EXT_VENDOR_PHONE AS supTel, a.CREATION_DATE AS orderDate FROM scc_sc_order_detail a LEFT JOIN scc_sc_order b ON a.ORDER_ID = b.ORDER_ID WHERE a.MATERIAL_CODE IS NOT NULL AND a.MATERIAL_CODE != '' AND a.EXT_AREA_CODE IS NOT NULL AND a.EXT_AREA_CODE != ''
AND DATE_FORMAT(a.CREATION_DATE, '%Y-%m') = #{localMoth,jdbcType=VARCHAR}
UNION ALL SELECT DATE_FORMAT(ssoh.ORDER_DATE , '%Y-%m') AS ym, ssoh.NO_TAX_PRICE AS noTaxPrices, ssoh.MATERIAL_CODE AS materialCode, ssoh.MATERIAL_NAME AS materialName, ssoh.AREA_CODE AS areaCode, ssoh.BRAND AS brand, ssoh.MATERIAL_DESCRIBE AS materialDescribe, ssoh.ORG_CODE AS orgCode, ssoh.ORG_NAME AS orgNmae, ssoh.TAX_RATE AS taxPrice, ssoh.LEAD_TIME AS leadTime, ssoh.SUP_CODE AS supCode, ssoh.SUP_NAME AS supName, ssoh.SUP_TEL AS supTel, ssoh.ORDER_DATE AS orderDate FROM scc_sc_order_history ssoh
AND DATE_FORMAT(ssoh.ORDER_DATE, '%Y-%m') = #{localMoth,jdbcType=VARCHAR}
) t WHERE concat(t.materialCode, '-', t.areaCode) IS NOT NULL GROUP BY t.materialCode, t.areaCode, t.ym
